package api_test

import (
	"encoding/json"
	"fmt"
	"reflect"
	"testing"

	"github.com/KogenAI/kogen-loop/api"
)

func TestEventMarshalJSONRejectsEnvelopeCollisions(t *testing.T) {
	for _, tc := range []struct {
		key   string
		value any
	}{
		{"protocol", "replacement"},
		{"seq", 2},
		{"time", "2026-01-02T00:00:00Z"},
		{"type", "response"},
	} {
		t.Run(tc.key, func(t *testing.T) {
			event := api.Event{Protocol: api.Protocol, Seq: 1, Time: "2026-01-01T00:00:00Z", Type: api.EventRequestStarted, Fields: map[string]any{tc.key: tc.value}}
			data, err := event.MarshalJSON()
			want := fmt.Sprintf("event field %q collides with the envelope", tc.key)
			if err == nil || err.Error() != want {
				t.Fatalf("MarshalJSON() = %s, %v; want error %q", data, err, want)
			}
		})
	}
}

func TestEventMarshalJSONFlattensOrdinaryFields(t *testing.T) {
	event := api.Event{Protocol: api.Protocol, Seq: 1, Time: "2026-01-01T00:00:00Z", Type: api.EventRequestStarted, Fields: map[string]any{"n": 3, "model": "test-model"}}
	data, err := event.MarshalJSON()
	if err != nil {
		t.Fatalf("MarshalJSON(): %v", err)
	}
	var got map[string]any
	if err := json.Unmarshal(data, &got); err != nil {
		t.Fatalf("invalid event JSON %q: %v", data, err)
	}
	want := map[string]any{"protocol": "kogen-loop/v1", "seq": float64(1), "time": "2026-01-01T00:00:00Z", "type": "request.started", "n": float64(3), "model": "test-model"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("encoded event = %#v; want %#v", got, want)
	}
}

